func isForbiddenOverrideMethod(m string) bool {
	for _, forbidden := range []string{http.MethodGet, http.MethodHead, http.MethodOptions, http.MethodTrace, http.MethodConnect} {
		if strings.EqualFold(m, forbidden) {
