	c.writeContentType(MIMEApplicationXMLCharsetUTF8)
	c.response.WriteHeader(code)
	if _, err = c.response.Write([]byte(xml.Header)); err != nil {
		return
	}
	_, err = c.response.Write(b)
	return
}

func (b *ValueBinder) duration(sourceParam string, dest *time.Duration, valueMustExist bool) *ValueBinder {
	if b.failFast && b.errors != nil {
		return b
	}

	value := b.ValueFunc(sourceParam)
	if value == "" {
		if valueMustExist {
			b.setError(b.ErrorFunc(sourceParam, []string{value}, "required field value is empty", nil))
		}
		return b
	}
	t, err := time.ParseDuration(value)
	if err != nil {
		b.setError(b.ErrorFunc(sourceParam, []string{value}, "failed to bind field value to Duration", err))
		return b
	}
	*dest = t
	return b
}

func TrimNewlineEnd(bytes []byte) []byte {
	bLen := len(bytes)
	if bLen > 1 && bytes[bLen-1] == '\n' {
		bytes = bytes[:bLen-1]
	}
	return bytes
}

func isTrustedPeer(remoteAddr string, checker *ipChecker) bool {
	// Unix socket peers are on the same host, so they are trusted like loopback addresses. net/http reports them
	// as an empty string, as "@" or "@name" (Linux, unnamed or abstract socket) or as the path of a bound socket.
	if remoteAddr == "" || remoteAddr[0] == '@' || remoteAddr[0] == '/' {
		return checker.trustLoopback
	}
	host, _, err := net.SplitHostPort(remoteAddr)
	if err != nil {
		host = remoteAddr
	}
	if i := strings.IndexByte(host, '%'); i != -1 { // IPv6 zone, e.g. "fe80::1%eth0"
		host = host[:i]
	}
	ip := net.ParseIP(host)
	return ip != nil && checker.trust(ip)
}
